    private fun assertMatches(name: String, timeline: (Double) -> Double, duration: Double) {
        val sample = swiftUI.getValue(name)
        assertEquals("$name duration", sample.duration, duration, 1e-12)
        var time = -0.05
        for (expected in sample.values) {
            val actual = timeline(time)
            // SwiftUI works its curves out in Float: a few millionths at most.
            assertTrue("$name at $time: SwiftUI $expected, here $actual", abs(expected - actual) <= 2e-6 * (1 + abs(expected)))
            time += sample.step
        }
    }

    private fun assertMatches(name: String, timeline: KeyframeTimeline<Double>) = assertMatches(name, timeline::value, timeline.duration)

    private fun track(vararg keyframes: Keyframe) = KeyframeTimeline.of(0.0, *keyframes)

    private fun bezier(x1: Double, y1: Double, x2: Double, y2: Double) = UnitCurve.bezier(Point(x1, y1), Point(x2, y2))

    @Test
    fun theAppsAnimationsMoveAsTheIPhonesDo() {
        val hop = PeekKeyframes.hop
        assertMatches("hop.rise", { hop.value(it).rise }, hop.duration)
        assertMatches("hop.turn", { hop.value(it).turn }, 0.7)
        for (muted in listOf(true, false)) {
            val bell = PeekKeyframes.bell(muted)
            val name = if (muted) "bell.muted" else "bell.unmuted"
            assertMatches("$name.angle", { bell.value(it).angle }, bell.tracks[0].duration)
            if (muted) assertMatches("$name.scale", { bell.value(it).scale }, 0.32)
            if (!muted) assertMatches("$name.waves", { bell.value(it).waves }, 0.656)
            // The muted bell's waves and the unmuted bell's scale stay as they were.
            var time = -0.05
            while (time < 1) {
                val pose = bell.value(time)
                if (muted) assertEquals(0.0, pose.waves, 0.0) else assertEquals(1.0, pose.scale, 0.0)
                time += 0.01
            }
        }
        assertMatches("delivered.nextUp", PeekKeyframes.deliveredNextUp)
        assertMatches("delivered.compact", PeekKeyframes.deliveredCompact)
        assertMatches("pull.pop", PeekKeyframes.pullPop)
        val greeting = PeekKeyframes.greeting
        assertMatches("greeting.lift", { greeting.value(it).lift }, greeting.duration)
        assertMatches("greeting.angle", { greeting.value(it).angle }, greeting.duration)
    }

    @Test
    fun linearAndCubicKeyframesHandTheirSpeedOn() {
        assertMatches("linear.cubic.linear", track(LinearKeyframe(1.0, 1.0), CubicKeyframe(3.0, 2.0), LinearKeyframe(2.0, 0.5)))
        assertMatches("cubic.linearEaseOut", track(CubicKeyframe(1.0, 1.0), LinearKeyframe(3.0, 0.5, UnitCurve.easeOut)))
        assertMatches("cubic.linearEaseIn", track(CubicKeyframe(1.0, 1.0), LinearKeyframe(3.0, 0.5, UnitCurve.easeIn)))
        assertMatches("linearBezier.cubic", track(LinearKeyframe(1.0, 1.0, bezier(0.3, 0.6, 0.7, 0.4)), CubicKeyframe(2.0, 1.0)))
        assertMatches("linear.cubic.cubic", track(LinearKeyframe(1.0, 1.0), CubicKeyframe(1.5, 1.0), CubicKeyframe(4.0, 1.0)))
        assertMatches("cubic.velocities", track(CubicKeyframe(1.0, 1.0, endVelocity = 5.0), CubicKeyframe(2.0, 1.0), CubicKeyframe(0.0, 1.0, startVelocity = -3.0)))
    }

    @Test
    fun springKeyframesLeaveAtTheSpeedTheyAreGivenAndStopWhereTheyAre() {
        val spring = Spring(duration = 0.5, bounce = 0.2)
        assertMatches("cubic.spring", track(CubicKeyframe(1.0, 1.0), SpringKeyframe(3.0, 1.0, spring)))
        assertMatches("spring.cubic", track(SpringKeyframe(1.0, 0.3, spring), CubicKeyframe(2.0, 1.0)))
        assertMatches("linear.spring", track(LinearKeyframe(1.0, 0.5), SpringKeyframe(0.0, 0.5, spring)))
        assertMatches("spring.spring", track(SpringKeyframe(1.0, 0.2, spring), SpringKeyframe(0.0, 0.5, Spring(duration = 0.5))))
        assertMatches("defaultSpring", track(SpringKeyframe(1.0, 0.5)))
        // The pop's spring is cut off before it settles, and holds there.
        assertEquals(swiftUI.getValue("pull.pop").values.last(), PeekKeyframes.pullPop.value(10.0), 2e-6)
        assertTrue(PeekKeyframes.pullPop.value(10.0) != 1.0)
    }

    @Test
    fun moveKeyframesJumpAndLeaveAtRest() {
        assertMatches("cubic.move.cubic", track(CubicKeyframe(1.0, 1.0), MoveKeyframe(4.0), CubicKeyframe(2.0, 1.0)))
        assertMatches("move.cubic.cubic", track(MoveKeyframe(2.0), CubicKeyframe(3.0, 1.0), CubicKeyframe(0.0, 1.0)))
    }

    @Test
    fun aRunningAnimationsSpeedCarriesIntoTheNextTimeline() {
        fun withSpeed(speed: Double, vararg keyframes: Keyframe) =
            KeyframeTimeline(0.0, listOf(KeyframeTrack({ it }, { _, value -> value }, keyframes.toList())), listOf(speed))
        assertMatches("initialVelocity.cubic", withSpeed(2.0, CubicKeyframe(1.0, 1.0), CubicKeyframe(3.0, 1.0)))
        assertMatches("initialVelocity.spring", withSpeed(4.0, SpringKeyframe(1.0, 0.5, Spring(duration = 0.5, bounce = 0.2))))
        assertMatches("initialVelocity.linear", withSpeed(4.0, LinearKeyframe(1.0, 0.5), CubicKeyframe(0.0, 0.5)))
    }

    @Test
    fun theAnimatorHoldsItsValueUntilPlayedAndItsLastAfter() {
        val animator = KeyframeAnimatorState(PeekKeyframes.Hop())
        assertEquals(PeekKeyframes.Hop(), animator.value(3.0))
        assertFalse(animator.isRunning(3.0))
        animator.play(4.0) { PeekKeyframes.hop }
        assertTrue(animator.isRunning(4.0))
        assertEquals(PeekKeyframes.hop.value(0.25), animator.value(4.25))
        assertEquals(animator.value(4.25), animator.current)
        assertTrue(animator.isRunning(4.69))
        assertFalse(animator.isRunning(4.71))
        assertEquals(PeekKeyframes.Hop(), animator.value(6.0))
    }

    @Test
    fun theGreetingPlaysAgainFromWhereItStopped() {
        // SignInView plays the greeting every 4.6 s; the second time its angle leaves from -0.8, not 0.
        val animator = KeyframeAnimatorState(PeekKeyframes.Greeting())
        animator.play(0.0) { PeekKeyframes.greeting }
        assertEquals(-0.8, animator.value(4.6).angle, 1e-12)
        animator.play(4.6) { PeekKeyframes.greeting }
        assertMatches("greeting.angle.again", { animator.value(4.6 + it).angle }, 4.6)
    }

    @Test
    fun playingAgainMidwayCarriesOnFromTheValueAndSpeedShown() {
        val animator = KeyframeAnimatorState(PeekKeyframes.Hop())
        animator.play(0.0) { PeekKeyframes.hop }
        val shown = animator.value(0.15)
        val before = (animator.value(0.15).rise - animator.value(0.15 - 1e-6).rise) / 1e-6
        animator.play(0.15) { PeekKeyframes.hop }
        assertEquals(shown, animator.value(0.15))
        val after = (animator.value(0.15 + 1e-6).rise - animator.value(0.15).rise) / 1e-6
        assertEquals(before, after, 0.01)
        assertEquals(PeekKeyframes.Hop(), animator.value(0.15 + 0.7))
    }
}
